contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool ok;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }

        uint balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(ok && balAfter == balBefore + amount && cBalAfter == cBalBefore + amount);
    }

    receive() external payable {}
}

